cat > /tmp/test-discrepancy.js << 'EOF'
import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const BIN = '/private/tmp/100-tricks-runs/d44/with/m5-weekly-plans/r10/bin/subtrack.js';

function cli(file, ...args) {
  const r = spawnSync(process.execPath, [BIN, ...args, '--file', file], { encoding: 'utf8' });
  return { code: r.status, out: r.stdout, err: r.stderr };
}

const dir = mkdtempSync(join(tmpdir(), 'test-'));
const file = join(dir, 'subs.json');

try {
  cli(file, 'add', 'Netflix', '12.99', '--since', '2026-09-14');
  cli(file, 'add', 'Cloud backup', '119.99', '--every', 'year', '--since', '2026-01-31');

  const list = cli(file, 'list');
  const total = cli(file, 'total');

  console.log('List output:');
  console.log(list.out);
  console.log('Total output:');
  console.log(total.out);

  // Parse the costs from list
  const listLines = list.out.trim().split('\n');
  let listSum = 0;
  for (const line of listLines) {
    const match = line.match(/€([\d,]+\.\d{2})\s+a month/);
    if (match) {
      const costStr = match[1].replace(',', '');
      const cost = parseFloat(costStr);
      listSum += cost;
    }
  }

  // Parse the total
  const totalMatch = total.out.match(/€([\d,]+\.\d{2})/);
  const totalValue = parseFloat(totalMatch[1].replace(',', ''));

  console.log(`List sum: €${listSum.toFixed(2)}`);
  console.log(`Total value: €${totalValue.toFixed(2)}`);
  console.log(`Discrepancy: €${(listSum - totalValue).toFixed(2)}`);
} finally {
  rmSync(dir, { recursive: true, force: true });
}
EOF
node /tmp/test-discrepancy.js
